/**
 * Stage 4's traffic cars: a small hatchback and a one-box van, photographed
 * from straight above (white cars, cut out of their studio backgrounds).
 *
 * Each car is two images drawn one over the other. `detail` is the whole
 * car as photographed. `paint` is only its white bodywork -- the bright,
 * colourless pixels, faded out toward the glass, trim and lamps -- and is
 * drawn on top with a tint. A tint multiplies, so the white panels take any
 * colour with the photo's own shading kept, and the glass, lamps and tyres
 * underneath stay as they are. One pair of textures makes every colour.
 *
 * `length` is the real car's length in metres (the size it is drawn at is
 * set from it against the player's car, see main.js); `px` the image size
 * and `bodyPx` the width of the body without its mirrors, in image pixels.
 */
export const MOB_CARS = {
  hatch: {
    length: 3.94,
    px: { w: 218, h: 400 },
    bodyPx: 180,
    detail: "data:image/png;base64,",
    paint: "data:image/png;base64,",
  },
  van: {
    length: 4.695,
    px: { w: 180, h: 400 },
    bodyPx: 152,
    detail: "data:image/png;base64,",
    paint: "data:image/png;base64,",
  },
};

/** Body colours, picked at random per car: mostly the whites, silvers and
 *  blacks real traffic is made of, with some colour among them. */
export const MOB_PAINTS = [
  0xf4f4f2, 0xf4f4f2, 0xe9e4d4,   // white, pearl
  0xbfc3c8, 0xbfc3c8, 0x7a7f86,   // silver, grey
  0x2b2d31, 0x2b2d31,             // black
  0xc2282b, 0x2758b4, 0x1e2b4c,   // red, blue, navy
  0xe3b322, 0x2f6b46, 0x8a1f2a,   // yellow, green, wine
];
